/* Custom recall questions for bosses (stations your Recall Drill doesn't cover). */
const CUSTOM_RECALL = [
  { id: "c3a", type: "fact", q: "Give two reasons the COCP is contraindicated for Sharon.", a: "Previous DVT, and she is a smoker over 35." },
  { id: "c3b", type: "why", q: "Why conserve the ovaries at hysterectomy under 65?", a: "Removing them raises all-cause mortality, cardiovascular disease, osteoporosis, dementia and depression; salpingectomy alone lowers ovarian cancer risk." },
  { id: "c3c", type: "why", q: "Why does endometrial ablation often fail in adenomyosis?", a: "The disease lies deep in the myometrium beyond the ablation depth, and the enlarged cavity raises failure rates." },
  { id: "c4a", type: "fact", q: "First-line medical treatments for endometriosis pain?", a: "NSAIDs, the COCP (continuous is fine) and progestogens (dienogest, norethisterone, LNG-IUS)." },
  { id: "c4b", type: "why", q: "Why give add-back therapy with a GnRH agonist?", a: "The hypo-oestrogenic state causes bone loss and vasomotor symptoms; add-back from the start prevents them without reducing efficacy." },
  { id: "c4c", type: "fact", q: "Imaging for suspected deep endometriosis?", a: "Expert transvaginal ultrasound or MRI." },
  { id: "c4d", type: "fact", q: "How do you confirm a structure is the ureter at laparoscopy?", a: "Peristalsis (vermiculation), tracing it from the pelvic brim, and its course under the uterine artery." },
  { id: "c4e", type: "fact", q: "How do you lower the recurrence of endometriosis after excision?", a: "Postoperative long-term hormonal suppression (COCP, progestogen or LNG-IUS)." },
  { id: "c5a", type: "num", q: "Therapeutic enoxaparin dose for PE?", a: "1 mg/kg twice daily or 1.5 mg/kg once daily." },
  { id: "c5b", type: "num", q: "How long do you anticoagulate a provoked VTE after surgery?", a: "3 months." },
  { id: "c5c", type: "why", q: "Why stop warfarin before conception?", a: "Warfarin embryopathy at 6–12 weeks; switch to LMWH before conceiving." },
  { id: "c5d", type: "fact", q: "Where is Palmer's point, and when do you use it?", a: "Left upper quadrant, about 3 cm below the costal margin in the midclavicular line; used when periumbilical adhesions are likely (previous midline laparotomy)." },
  { id: "c5e", type: "fact", q: "Pregnancy thromboprophylaxis for heterozygous factor V Leiden with a previous VTE?", a: "Antenatal LMWH and 6 weeks postnatal LMWH, planned with haematology." },
  { id: "c6a", type: "fact", q: "What does DRSABCD stand for?", a: "Danger, Response, Send for help, Airway, Breathing, Circulation, Defibrillation." },
  { id: "c6b", type: "why", q: "What causes cervical shock?", a: "A vagal reflex from cervical stretch or dilatation, causing bradycardia, hypotension and syncope." },
  { id: "c6c", type: "num", q: "Atropine dose for symptomatic bradycardia?", a: "500–600 micrograms IV, repeated to a maximum of 3 mg." },
  { id: "c6d", type: "num", q: "IM adrenaline dose for adult anaphylaxis?", a: "0.5 mg (0.5 mL of 1:1000) IM into the anterolateral thigh, repeated every 5 minutes as needed." },
  { id: "c6e", type: "fact", q: "Name three ways to reduce pain and vasovagal risk at IUD insertion.", a: "Any three of: pre-procedure NSAID, cervical or paracervical block, lidocaine gel, experienced operator, lying her down, talking her through it." },
  { id: "c6f", type: "fact", q: "Give two clinical differences between a vasovagal episode and anaphylaxis.", a: "Vasovagal: bradycardia, pallor, recovery when lying flat. Anaphylaxis: tachycardia, urticaria or flushing, wheeze or angioedema." },
  { id: "c7a", type: "why", q: "Why time elective surgery for an adnexal mass after 14 weeks?", a: "The placenta has taken over from the corpus luteum, the miscarriage risk is lower, and the uterus is still small enough for access." },
  { id: "c7b", type: "fact", q: "If the corpus luteum is removed before 10 weeks, what do you give?", a: "Progesterone support until about 10–12 weeks." },
  { id: "c7c", type: "fact", q: "Differentials for acute right-sided pain at 14 weeks with a known adnexal mass?", a: "Ovarian torsion, cyst rupture or haemorrhage, appendicitis (also red degeneration of a fibroid)." },
  { id: "c7d", type: "why", q: "Does normal Doppler flow exclude ovarian torsion?", a: "No: flow can persist in partial or intermittent torsion. It's a clinical diagnosis, so operate if suspected." },
  { id: "c7e", type: "fact", q: "Management options for a second-trimester fetal death?", a: "Expectant, medical induction (mifepristone 200 mg then misoprostol), or surgical D&E by an experienced operator." },
  { id: "c7f", type: "fact", q: "Investigations after a second-trimester loss?", a: "Kleihauer, infection screen (TORCH, parvovirus, syphilis), antiphospholipid antibodies, TFT and HbA1c, and with consent postmortem, placental histology and karyotype." },
  { id: "c7g", type: "fact", q: "Pregnancy care changes for a BMI of 38?", a: "5 mg folate, early GDM screen, VTE risk assessment, anaesthetic review, serial growth scans, aspirin if other pre-eclampsia risk factors." },
  { id: "c8a", type: "num", q: "When is the benefit-risk balance of MHT most favourable?", a: "Under 60 or within 10 years of menopause." },
  { id: "c8b", type: "why", q: "Why does a woman with a uterus need a progestogen with oestrogen?", a: "Unopposed oestrogen causes endometrial hyperplasia and cancer." },
  { id: "c8c", type: "fact", q: "Treatment for genitourinary syndrome of menopause?", a: "Low-dose vaginal oestrogen (for example estriol), plus moisturisers and lubricants." },
  { id: "c9a", type: "num", q: "Lifetime ovarian cancer risk with BRCA1, and recommended RRSO age?", a: "About 40–45%; RRSO at 35–40 once childbearing is complete." },
  { id: "c9b", type: "why", q: "Why avoid paroxetine and fluoxetine with tamoxifen?", a: "They inhibit CYP2D6, reducing conversion of tamoxifen to endoxifen, its active metabolite." },
  { id: "c9c", type: "why", q: "What does tamoxifen do to the endometrium?", a: "As a partial oestrogen agonist it causes polyps, hyperplasia and a 2–3 times risk of endometrial cancer." },
  { id: "c9d", type: "fact", q: "Treatment for atypical hyperplasia in a woman not wanting fertility?", a: "Total hysterectomy with bilateral salpingo-oophorectomy (no ablation), with gynae-oncology input." }
];

